package vn.smartfarm.iot.telemetry;
import java.util.*;import java.util.concurrent.*;import java.util.function.Consumer;
import org.junit.jupiter.api.Test;import software.amazon.awssdk.crt.mqtt.*;import vn.smartfarm.iot.irrigation.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class CircuitValveTransportTest {
 @Test void onlySubscribedCircuitGetsExactNonRetainedCommandTopic()throws Exception{
  var c=mock(CircuitValveControl.class);when(c.enabled()).thenReturn(true);when(c.topics()).thenReturn(List.of("smartfarm/FARM001/VALVE08/demo/status","smartfarm/FARM001/VALVE08/demo/ack"));
  var connection=mock(MqttClientConnection.class);when(connection.subscribe(anyString(),any(QualityOfService.class),org.mockito.ArgumentMatchers.<Consumer<MqttMessage>>any())).thenReturn(CompletableFuture.completedFuture(1));when(connection.publish(any(MqttMessage.class))).thenReturn(CompletableFuture.completedFuture(1));when(connection.disconnect()).thenReturn(CompletableFuture.completedFuture(null));
  var ingestion=new TelemetryIngestion(mock(vn.smartfarm.iot.nodes.TelemetryRouter.class),mock(vn.smartfarm.iot.control.PumpService.class),mock(vn.smartfarm.iot.monitoring.MqttHealth.class),mock(IrrigationDemo.class),mock(CircuitValveMonitor.class),c,false,false);
  try{var f=TelemetryIngestion.class.getDeclaredField("connection");f.setAccessible(true);f.set(ingestion,connection);var method=TelemetryIngestion.class.getDeclaredMethod("subscribeStreams");method.setAccessible(true);method.invoke(ingestion);
   assertTrue(ingestion.circuitValveConnected("VALVE08"));assertFalse(ingestion.circuitValveConnected("VALVE09"));assertFalse(ingestion.controlConnected());assertThrows(IllegalStateException.class,()->ingestion.publishCircuitValve("VALVE09",new byte[]{1}));assertThrows(IllegalArgumentException.class,()->ingestion.publishCircuitValve("VALVE01",new byte[]{1}));
   ingestion.publishCircuitValve("VALVE08",new byte[]{1});var capture=org.mockito.ArgumentCaptor.forClass(MqttMessage.class);verify(connection).publish(capture.capture());assertEquals("smartfarm/FARM001/VALVE08/demo/command",capture.getValue().getTopic());assertFalse(capture.getValue().getRetain());assertEquals(QualityOfService.AT_LEAST_ONCE,capture.getValue().getQos());
  }finally{ingestion.destroy();}
 }
 @Test void blockedCircuitReceiverDoesNotBlockPumpStatus()throws Exception{
  var c=mock(CircuitValveControl.class);when(c.enabled()).thenReturn(true);when(c.topics()).thenReturn(List.of("smartfarm/FARM001/VALVE08/demo/status"));var pump=mock(vn.smartfarm.iot.control.PumpService.class);var connection=mock(MqttClientConnection.class);var callbacks=new HashMap<String,Consumer<MqttMessage>>();when(connection.subscribe(anyString(),any(QualityOfService.class),org.mockito.ArgumentMatchers.<Consumer<MqttMessage>>any())).thenAnswer(a->{callbacks.put(a.getArgument(0),a.getArgument(2));return CompletableFuture.completedFuture(1);});when(connection.disconnect()).thenReturn(CompletableFuture.completedFuture(null));
  var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var received=new CountDownLatch(1);doAnswer(a->{entered.countDown();assertTrue(release.await(4,TimeUnit.SECONDS));return null;}).when(c).receive(anyString(),any(byte[].class),eq(false));doAnswer(a->{received.countDown();return null;}).when(pump).receive(anyString(),any(byte[].class));
  var ingestion=new TelemetryIngestion(mock(vn.smartfarm.iot.nodes.TelemetryRouter.class),pump,mock(vn.smartfarm.iot.monitoring.MqttHealth.class),mock(IrrigationDemo.class),mock(CircuitValveMonitor.class),c,false,true);
  try{var f=TelemetryIngestion.class.getDeclaredField("connection");f.setAccessible(true);f.set(ingestion,connection);var m=TelemetryIngestion.class.getDeclaredMethod("subscribeStreams");m.setAccessible(true);m.invoke(ingestion);callbacks.get("smartfarm/FARM001/VALVE08/demo/status").accept(new MqttMessage("smartfarm/FARM001/VALVE08/demo/status",new byte[]{1},QualityOfService.AT_LEAST_ONCE,false));assertTrue(entered.await(1,TimeUnit.SECONDS));callbacks.get("smartfarm/FARM001/PUMP01/status").accept(new MqttMessage("smartfarm/FARM001/PUMP01/status",new byte[]{1},QualityOfService.AT_LEAST_ONCE,false));assertTrue(received.await(2,TimeUnit.SECONDS));verify(connection,never()).publish(any(MqttMessage.class));}finally{release.countDown();ingestion.destroy();}
 }
}
